<script setup lang="ts">
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import type { ConfigurationDisplayTypeOption, ConfigurationTemplateValue } from '@/types/configurationTemplate';
const model = defineModel<any>({ required: true });
defineProps<{ displayTypes: ConfigurationDisplayTypeOption[] }>();
function usesValues(type: string): boolean { return !['text', 'number'].includes(type); }
function addValue(): void { model.value.values.push({ id: null, label: '', value: '', description: '', swatch_color: '#000000', image_path: null, price_adjustment_cents: 0, currency: 'USD', is_default: false, is_active: true } satisfies ConfigurationTemplateValue); }
</script>
<template><div class="space-y-6"><div class="grid gap-4 md:grid-cols-2"><label class="space-y-1.5 text-sm"><span class="font-medium">Name</span><Input v-model="model.name" /></label><label class="space-y-1.5 text-sm"><span class="font-medium">Code</span><Input v-model="model.code" placeholder="Generated from name" /></label><label class="space-y-1.5 text-sm"><span class="font-medium">Display type</span><select v-model="model.display_type" class="h-10 w-full rounded-md border bg-background px-3"><option v-for="type in displayTypes" :key="type.value" :value="type.value">{{ type.label }}</option></select></label><label class="space-y-1.5 text-sm"><span class="font-medium">Sort order</span><Input v-model="model.sort_order" type="number" min="0" /></label><label class="md:col-span-2 space-y-1.5 text-sm"><span class="font-medium">Description</span><textarea v-model="model.description" rows="3" class="w-full rounded-md border bg-background px-3 py-2" /></label></div><div class="flex flex-wrap gap-5 text-sm"><label class="flex gap-2"><input v-model="model.is_required_default" type="checkbox" /> Required by default</label><label v-if="model.display_type === 'checkbox'" class="flex gap-2"><input v-model="model.allows_multiple_default" type="checkbox" /> Allow multiple by default</label><label class="flex gap-2"><input v-model="model.is_active" type="checkbox" /> Active</label></div><div v-if="model.display_type === 'number'" class="grid gap-4 sm:grid-cols-3"><label class="space-y-1.5 text-sm"><span>Minimum</span><Input v-model="model.minimum_value" type="number" /></label><label class="space-y-1.5 text-sm"><span>Maximum</span><Input v-model="model.maximum_value" type="number" /></label><label class="space-y-1.5 text-sm"><span>Step</span><Input v-model="model.step_value" type="number" /></label></div><section v-if="usesValues(model.display_type)" class="space-y-3 border-t pt-5"><div class="flex justify-between"><div><h2 class="font-semibold">Template Values</h2><p class="text-sm text-muted-foreground">These values are copied into an asset when the template is selected.</p></div><Button type="button" variant="outline" @click="addValue">Add Value</Button></div><div v-for="(value,index) in model.values" :key="value.id ?? index" class="grid gap-3 rounded-xl border p-4 lg:grid-cols-[1fr_1fr_150px_120px_auto] lg:items-end"><label class="space-y-1.5 text-sm"><span>Label</span><Input v-model="value.label" /></label><label class="space-y-1.5 text-sm"><span>Internal value</span><Input v-model="value.value" /></label><label class="space-y-1.5 text-sm"><span>Price adjustment</span><Input :model-value="(value.price_adjustment_cents/100).toFixed(2)" type="number" step="0.01" @update:model-value="value.price_adjustment_cents = Math.round(Number($event || 0)*100)" /></label><label v-if="model.display_type === 'color_swatch'" class="space-y-1.5 text-sm"><span>Color</span><input v-model="value.swatch_color" type="color" class="h-10 w-full rounded border p-1" /></label><div v-else></div><div class="flex justify-end gap-2"><label class="text-xs"><input v-model="value.is_default" type="checkbox" /> Default</label><Button type="button" size="sm" variant="destructive" @click="model.values.splice(index,1)">Remove</Button></div></div></section></div></template>
